    v_req.user_id, p_withdrawal_id::TEXT, v_transfer_id
  );

  UPDATE withdrawal_requests
     SET status = 'approved',
         admin_note = p_reason,
         approved_by = v_actor,
         approved_at = NOW(),
         ledger_approve_debit_id = v_ledger_id,
         system_payout_transfer_id = v_transfer_id
   WHERE id = p_withdrawal_id;

